class Solution { public: bool containsNearbyAlmostDuplicate(vector<int>& nums,int indexDiff,int valueDiff){set<long long> window;for(int i=0;i<(int)nums.size();++i){if(i>indexDiff)window.erase(nums[i-indexDiff-1]);long long value=nums[i];auto it=window.lower_bound(value-(long long)valueDiff);if(it!=window.end()&&*it<=value+(long long)valueDiff)return true;window.insert(value);}return false;} };
